use kernel_core::{codec,model::{Expr,Model,Q,Row,Var},proof::*,rpa,verify::{verify_request,verify_lp_refutation,Limits}};
fn q(n:i64)->Q{Q::from_integer(n.into())}
fn e(c:i64,t:&[(u32,i64)])->Expr{Expr{constant:q(c),terms:t.iter().map(|(i,c)|(*i,q(*c))).collect()}}
fn v(n:&str,int:bool,lo:Option<i64>,hi:Option<i64>)->Var{Var{name:n.into(),integer:int,lower:lo.map(q),upper:hi.map(q)}}
fn row(n:&str,e:Expr,eq:bool)->Row{Row{name:n.into(),expr:e,lower:if eq{Some(q(0))}else{None},upper:Some(q(0))}}
fn lin(id:u32,kind:Kind,terms:&[(Ref,i64)])->Step{Step::Lin{id,kind,constant:q(0),terms:terms.iter().map(|(r,c)|(r.clone(),q(*c))).collect()}}
fn claim()->Claim{Claim{input_halfspace:None,input_objective_level:None,reverse:false,input_integers:true,output_integers:true,objective:Objective::Equal,projection:vec![],affine_projection:vec![(Expr::var(0),e(0,&[(0,1),(1,-1)])),(Expr::var(1),e(0,&[(2,1),(3,1)]))],inverse:None,input_objective_lower:None}}
fn fixture()->(Model,Model,Certificate,Request){
 let source=Model{name:"signed_input".into(),vars:vec![v("f",false,None,None),v("z",true,Some(0),Some(1))],rows:vec![row("upper",e(0,&[(0,1),(1,-2)]),false),row("lower",e(0,&[(0,-1),(1,-2)]),false)],objective:e(5,&[(1,3)])};
 let target=Model{name:"direction_pair".into(),vars:vec![v("p",false,Some(0),None),v("n",false,Some(0),None),v("u",true,Some(0),Some(1)),v("v",true,Some(0),Some(1))],rows:vec![row("upper_p",e(0,&[(0,1),(2,-2)]),false),row("upper_n",e(0,&[(1,1),(3,-2)]),false)],objective:e(5,&[(2,3),(3,3)])};
 let d=SignedWitness{capacity:q(2),flow:Expr::var(0),activation:Expr::var(1),checks:vec![Ref::VarLower(1),Ref::VarUpper(1),Ref::VarInt(1),Ref::RowUpper(0),Ref::RowUpper(1)]};
 let body=Block{steps:vec![lin(0,Kind::Eq,&[(Ref::RowEq(3),3)])],end:End::Return{map:(2..6).map(Expr::var).collect(),checks:vec![Ref::VarLower(2),Ref::VarLower(3),Ref::VarLower(4),Ref::VarUpper(4),Ref::VarInt(4),Ref::VarLower(5),Ref::VarUpper(5),Ref::VarInt(5),Ref::RowUpper(4),Ref::RowUpper(5),Ref::Local(0),Ref::RowEq(2),Ref::RowEq(3)]}};
 let c=Certificate{improvements:vec![], claims:vec![claim()],blocks:vec![Block{steps:vec![],end:End::SignedLift{decompositions:vec![d],body:Box::new(body)}}],points:vec![],bijections:vec![]};let r=Request{improvements:vec![], claims:c.claims.clone(),points:vec![],bijections:vec![]};(source,target,c,r)
}
fn check(s:&Model,t:&Model,c:&Certificate,r:&Request)->Result<kernel_core::verify::Statistics,String>{verify_request(s,t,c,r,&Limits::default())}
fn inside(c:&mut Certificate)->(&mut Vec<SignedWitness>,&mut Block){let End::SignedLift{decompositions,body}=&mut c.blocks[0].end else{panic!()};(decompositions,body)}
#[test]fn full_signed_to_directed_contract_and_versioned_roundtrip(){let(s,t,c,r)=fixture();let stats=check(&s,&t,&c,&r).unwrap();assert_eq!(stats.signed_lifts,1);assert_eq!(stats.signed_generated_variables,4);assert_eq!(stats.signed_generated_rows,4);assert_eq!(stats.signed_generated_terms,10);assert_eq!(stats.obligations,13);let b=codec::encode_certificate(&c).unwrap();assert_eq!(&b[4..6],&8u16.to_le_bytes());assert_eq!(codec::decode_certificate(&b).unwrap(),c);let txt=rpa::disassemble(&c).unwrap();assert_eq!(rpa::assemble(&txt).unwrap(),c);for old in 1..8{assert!(rpa::assemble(&txt.replacen("RPA 8",&format!("RPA {old}"),1)).is_err());let mut bad=b.clone();bad[4..6].copy_from_slice(&(old as u16).to_le_bytes());assert!(codec::decode_certificate(&bad).is_err());}}
#[test]fn all_five_premises_and_middle_item_use_only_parent_scope(){let(s,t,c,r)=fixture();for i in 0..5{let mut bad=c.clone();inside(&mut bad).0[0].checks[i]=Ref::Exact;if i==2{inside(&mut bad).0[0].checks[i]=Ref::VarInt(0);}assert!(check(&s,&t,&bad,&r).is_err(),"{i}");let mut bad=c.clone();inside(&mut bad).0[0].checks.remove(i);assert!(check(&s,&t,&bad,&r).is_err());}
 for what in 0..4{let mut bad=c.clone();let d=&mut inside(&mut bad).0[0];match what{0=>d.flow=Expr::var(2),1=>d.checks[2]=Ref::VarInt(4),2=>d.checks[3]=Ref::RowUpper(4),_=>d.capacity=q(3)}assert!(check(&s,&t,&bad,&r).is_err());}
 let mut bad=c.clone();let ds=inside(&mut bad).0;ds.push(ds[0].clone());ds.push(ds[0].clone());ds[1].activation=Expr::var(4);assert!(check(&s,&t,&bad,&r).is_err());
 let mut dead=c.clone();dead.blocks[0].steps=vec![lin(42,Kind::Le,&[(Ref::RowUpper(0),1)]),Step::Drop{ids:vec![42]}];inside(&mut dead).0[0].checks[3]=Ref::Local(42);assert!(check(&s,&t,&dead,&r).is_err());}
#[test]fn integer_mode_inverse_and_refutation_restrictions_survive(){let(s,t,c,r)=fixture();let mut bad=c.clone();bad.claims[0].input_integers=false;let rr=Request{improvements:vec![], claims:bad.claims.clone(),..r.clone()};assert!(check(&s,&t,&bad,&rr).unwrap_err().contains("integer input mode"));assert!(verify_lp_refutation(&s,&c.blocks[0],&Limits::default()).unwrap_err().contains("only Absurd/Split"));let mut bad=c.clone();bad.claims[0].inverse=Some(1);let mut reverse=bad.claims[0].clone();reverse.reverse=true;reverse.inverse=Some(0);reverse.affine_projection.clear();bad.claims.push(reverse);bad.blocks.push(Block{steps:vec![],end:End::Return{map:vec![e(0,&[(0,1),(1,-1)]),e(0,&[(2,1),(3,1)])],checks:vec![]}});let rr=Request{improvements:vec![], claims:bad.claims.clone(),..r};assert!(check(&s,&t,&bad,&rr).unwrap_err().contains("inverse requires affine"));}
#[test]fn all_actual_output_obligations_still_apply_jointly(){let(s,t,c,r)=fixture();for what in 0..8{let mut bad=c.clone();let body=inside(&mut bad).1;let End::Return{map,checks}=&mut body.end else{panic!()};match what{0=>{checks.remove(6);},1=>checks.push(Ref::Exact),2=>map[0]=map[1].clone(),3=>map[2]=e(0,&[]),4=>checks[8]=Ref::Exact,5=>checks[10]=Ref::Exact,6=>checks[11]=Ref::Exact,_=>{map.pop();}}assert!(check(&s,&t,&bad,&r).is_err(),"{what}");}
 let mut output=t.clone();output.vars[0].upper=Some(q(0));assert!(check(&s,&output,&c,&r).is_err());let mut output=t.clone();output.objective.constant=q(4);assert!(check(&s,&output,&c,&r).is_err());let mut source=s.clone();source.rows[0].upper=Some(q(1));assert!(check(&source,&t,&c,&r).is_err());}
#[test]fn nested_extensions_and_siblings_keep_old_prefix_and_isolated_facts(){let(s,t,c,r)=fixture();let mut nested=c.clone();let (_,body)=inside(&mut nested);*body=Block{steps:vec![],end:End::MenuLift{menus:vec![MenuWitness{maximum_index:0,activation:Expr::var(1),index:Expr::zero(),checks:vec![Ref::VarLower(1),Ref::VarUpper(1),Ref::VarInt(1),Ref::Exact,Ref::Exact,Ref::Exact]}],body:Box::new(body.clone())}};assert_eq!(codec::certificate_version(&nested).unwrap(),8);assert_eq!(check(&s,&t,&nested,&r).unwrap().menu_lifts,1);
 let mut fork=c.clone();let base=fork.blocks[0].clone();fork.blocks[0]=Block{steps:vec![],end:End::Split{expression:Expr::var(0),integer:None,left:Box::new(base.clone()),right:Box::new(base)}};assert_eq!(check(&s,&t,&fork,&r).unwrap().signed_lifts,2);let End::Split{right,..}=&mut fork.blocks[0].end else{panic!()};let End::SignedLift{decompositions,..}=&mut right.end else{panic!()};decompositions[0].checks[2]=Ref::Local(0);assert!(check(&s,&t,&fork,&r).is_err());}
#[test]fn shared_work_depth_counts_truncation_and_unknown_fields_are_bounded(){let(s,t,c,r)=fixture();let stats=check(&s,&t,&c,&r).unwrap();for l in [Limits{work:stats.work-1,..Limits::default()},Limits{depth:1,..Limits::default()},Limits{live_facts:0,..Limits::default()}]{assert!(verify_request(&s,&t,&c,&r,&l).unwrap_err().starts_with("RESOURCE_LIMIT"));}let b=codec::encode_certificate(&c).unwrap();for n in 0..b.len(){let mut truncated=b[..n].to_vec();if n>=16{truncated[8..16].copy_from_slice(&(n as u64).to_le_bytes());}assert!(codec::decode_certificate(&truncated).is_err());}let mut value=serde_json::to_value(&c).unwrap();value["blocks"][0]["end"]["SignedLift"]["decompositions"][0]["ignored"]=true.into();assert!(rpa::assemble(&format!("RPA 8\n{value}")).is_err());
 for i in 16..b.len(){for value in [0,1,127,255]{let mut bytes=b.clone();bytes[i]=value;if let Ok(decoded)=codec::decode_certificate(&bytes){let _=check(&s,&t,&decoded,&r);}}}}
#[test]fn independent_binary_vector_all_prefixes_and_hostile_counts(){let s=codec::decode_model(include_bytes!("../../../tests/vectors/signed-source.mcm")).unwrap();let t=codec::decode_model(include_bytes!("../../../tests/vectors/signed-target.mcm")).unwrap();let bytes=include_bytes!("../../../tests/vectors/signed-v8.rpx");let c=codec::decode_certificate(bytes).unwrap();assert_eq!(codec::encode_certificate(&c).unwrap(),bytes);let r=Request{improvements:vec![], claims:c.claims.clone(),points:vec![],bijections:vec![]};check(&s,&t,&c,&r).unwrap();assert!(codec::decode_certificate(include_bytes!("../../../tests/vectors/invalid-v8-terminal-v7.rpx")).is_err());assert!(codec::decode_certificate(include_bytes!("../../../tests/vectors/invalid-v8-count.rpx")).unwrap_err().starts_with("RESOURCE_LIMIT"));for n in 0..bytes.len(){let mut changed=bytes[..n].to_vec();if n>=16{changed[8..16].copy_from_slice(&(n as u64).to_le_bytes());}assert!(codec::decode_certificate(&changed).is_err());}}
#[test]fn full_bijection_compositions_survive_signed_extension(){
 let m=Model{name:"binary".into(),vars:vec![v("x",true,Some(0),Some(1))],rows:vec![],objective:Expr::var(0)};let mut f=claim();f.affine_projection.clear();let mut g=f.clone();g.reverse=true;
 let forward=Block{steps:vec![],end:End::Return{map:vec![Expr::var(0)],checks:vec![Ref::VarLower(0),Ref::VarUpper(0),Ref::VarInt(0),Ref::Exact]}};
 let mut body=forward.clone();let End::Return{checks,..}=&mut body.end else{panic!()};checks.push(Ref::Exact);
 let reverse=Block{steps:vec![],end:End::SignedLift{decompositions:vec![SignedWitness{capacity:q(0),flow:Expr::zero(),activation:Expr::var(0),checks:vec![Ref::VarLower(0),Ref::VarUpper(0),Ref::VarInt(0),Ref::Exact,Ref::Exact]}],body:Box::new(body)}};
 let pair=BijectionClaim{forward_claim:0,reverse_claim:1};let c=Certificate{improvements:vec![], claims:vec![f,g],blocks:vec![forward,reverse],points:vec![],bijections:vec![BijectionWitness{claim:pair.clone(),injectivity:EqualityProof{steps:vec![],checks:vec![Ref::RowEq(0)]}}]};let r=Request{improvements:vec![], claims:c.claims.clone(),points:vec![],bijections:vec![pair]};assert_eq!(check(&m,&m,&c,&r).unwrap().bijections,1);
 let mut bad=c.clone();let End::SignedLift{body,..}=&mut bad.blocks[1].end else{panic!()};let End::Return{checks,..}=&mut body.end else{panic!()};checks.pop();assert!(check(&m,&m,&bad,&r).is_err());
}
